SELECT BANNER_ID, TITLE, LINK_URL, POSITION, START_YMD, END_YMD, USE_YN, ORDR, ATCH_FILE_GRPID, REGIST_DT FROM BANNER
AND TITLE LIKE '%' || #{searchKeyword} || '%'
AND POSITION = #{position}
AND USE_YN = #{useYn}
ORDER BY ORDR, REGIST_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*)
FROM BANNER


		AND TITLE LIKE '%' || #{searchKeyword} || '%'


		AND POSITION = #{position}


		AND USE_YN = #{useYn}
